using System;using System.IO;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Diagnostics;
public class Evidence {public string File,Architecture,Interface,Kind;public long Offset;}
public class BinaryInfo {public string File,Architecture,Hash,Error;public List<string> Imports=new List<string>(),Exports=new List<string>();public List<Evidence> Evidence=new List<Evidence>();}
public class AnalysisReport {public string Game,Root,Steam,AppId;public List<BinaryInfo> Files=new List<BinaryInfo>();public List<string> Warnings=new List<string>();public Dictionary<string,string> Probes=new Dictionary<string,string>();public int Scanned;}
public static class Analyzer {
 public static readonly Regex Versions=new Regex(@"(?<![A-Za-z0-9_])(?:Steam[A-Za-z]+[0-9]{3}|STEAM[A-Z0-9_]*INTERFACE[A-Z0-9_]*[0-9]{3}|STEAM[A-Z]+_V[0-9]{3})(?![A-Za-z0-9_])",RegexOptions.Compiled);
 public static readonly Dictionary<string,string> Fallbacks=new Dictionary<string,string>{{"SteamClient023","SteamClient021"},{"SteamFriends018","SteamFriends017"},{"STEAMAPPS_INTERFACE_VERSION009","STEAMAPPS_INTERFACE_VERSION008"},{"SteamApps009","STEAMAPPS_INTERFACE_VERSION008"},{"STEAMUGC_INTERFACE_VERSION021","STEAMUGC_INTERFACE_VERSION020"},{"SteamUGC021","STEAMUGC_INTERFACE_VERSION020"},{"STEAMREMOTEPLAY_INTERFACE_VERSION004","STEAMREMOTEPLAY_INTERFACE_VERSION002"},{"SteamRemotePlay004","STEAMREMOTEPLAY_INTERFACE_VERSION002"},{"STEAMREMOTEPLAY_INTERFACE_VERSION003","STEAMREMOTEPLAY_INTERFACE_VERSION002"},{"SteamRemotePlay003","STEAMREMOTEPLAY_INTERFACE_VERSION002"}};
 static IEnumerable<string> Walk(string root,List<string> warnings){var stack=new Stack<string>();stack.Push(root);int dirs=0;while(stack.Count>0){string dir=stack.Pop();if(++dirs>100000){warnings.Add("Directory limit reached");yield break;}string[] files=null,children=null;try{files=Directory.GetFiles(dir);children=Directory.GetDirectories(dir);}catch(Exception e){warnings.Add(dir+": "+e.Message);}if(files!=null)foreach(string p in files){string ext=Path.GetExtension(p);if(ext.Equals(".dll",StringComparison.OrdinalIgnoreCase)||ext.Equals(".exe",StringComparison.OrdinalIgnoreCase))yield return p;}if(children!=null)foreach(string child in children)try{string name=Path.GetFileName(child);if((File.GetAttributes(child)&FileAttributes.ReparsePoint)!=0||name.StartsWith("LegacySteam",StringComparison.OrdinalIgnoreCase)||name.StartsWith(".LegacySteam",StringComparison.OrdinalIgnoreCase))continue;stack.Push(child);}catch(Exception e){warnings.Add(e.Message);}}}
 public static AnalysisReport Analyze(Game game,string steam,Action<string> log){var report=new AnalysisReport{Game=game.Name,Root=game.Root,Steam=steam,AppId=game.AppId};long total=0;foreach(string file in Walk(game.Root,report.Warnings)){if(++report.Scanned>20000){report.Warnings.Add("File limit reached");break;}try{long size=new FileInfo(file).Length;if(size>512L*1024*1024){report.Warnings.Add("Skipped file over 512 MiB: "+file);continue;}total+=size;if(total>20L*1024*1024*1024){report.Warnings.Add("20 GiB analysis limit reached");break;}BinaryInfo b=ReadBinary(file,game.Root);if(b.Evidence.Count>0||b.Imports.Count>0||b.Exports.Count>0||Path.GetFileName(file).IndexOf("steam",StringComparison.OrdinalIgnoreCase)>=0)report.Files.Add(b);if(report.Scanned%20==0)log("Analyzed files: "+report.Scanned);}catch(Exception e){report.Warnings.Add(file+": "+e.Message);}}log("Static analysis complete: "+report.Scanned+" files; Steam-related files: "+report.Files.Count);Probe(report,log);return report;}
 public static BinaryInfo ReadBinary(string file,string root){var b=new BinaryInfo{File=file.Substring(Path.GetFullPath(root).TrimEnd(new char[]{Path.DirectorySeparatorChar}).Length).TrimStart(new char[]{Path.DirectorySeparatorChar}),Architecture="Unknown",Hash=Core.Hash(file)};try{Pe(file,b);}catch(Exception e){b.Error="PE metadata: "+e.Message;}var seen=new HashSet<string>();using(var f=File.OpenRead(file)){byte[] buffer=new byte[1024*1024+256];int overlap=0,n;long origin=0;while((n=f.Read(buffer,overlap,buffer.Length-overlap))>0){int count=overlap+n;Extract(Encoding.GetEncoding(28591).GetString(buffer,0,count),b,seen,origin,1,"ASCII string");Extract(Encoding.Unicode.GetString(buffer,0,count-(count%2)),b,seen,origin,2,"UTF-16 string");if(count>1)Extract(Encoding.Unicode.GetString(buffer,1,(count-1)-((count-1)%2)),b,seen,origin+1,2,"UTF-16 string");int keep=Math.Min(256,count);Buffer.BlockCopy(buffer,count-keep,buffer,0,keep);origin+=count-keep;overlap=keep;}}return b;}
 static void Extract(string s,BinaryInfo b,HashSet<string> seen,long origin,int scale,string kind){foreach(Match m in Versions.Matches(s)){long offset=origin+(long)m.Index*scale;string key=m.Value+"@"+offset;if(seen.Add(key)&&b.Evidence.Count<10000)b.Evidence.Add(new Evidence{File=b.File,Architecture=b.Architecture,Interface=m.Value,Offset=offset,Kind=kind});}}
 class Section {public uint Va,VirtualSize,Raw,Size;}
 static void Pe(string file,BinaryInfo b){using(var f=File.OpenRead(file))using(var r=new BinaryReader(f)){Func<long,uint> u32=p=>{if(p<0||p+4>f.Length)throw new InvalidDataException("Invalid PE offset");f.Position=p;return r.ReadUInt32();};Func<long,ushort> u16=p=>{if(p<0||p+2>f.Length)throw new InvalidDataException("Invalid PE offset");f.Position=p;return r.ReadUInt16();};if(u16(0)!=0x5a4d)throw new InvalidDataException("Not PE");long pe=u32(0x3c);if(u32(pe)!=0x4550)throw new InvalidDataException("Bad PE signature");ushort machine=u16(pe+4),count=u16(pe+6),size=u16(pe+20);b.Architecture=machine==0x14c?"x86":machine==0x8664?"x64":machine==0xaa64?"ARM64":"Other";long opt=pe+24;ushort magic=u16(opt);if(magic!=0x10b&&magic!=0x20b)throw new InvalidDataException("Unknown optional header");long dirs=opt+(magic==0x20b?112:96);if(size<dirs-opt+16)throw new InvalidDataException("Missing data directories");var sections=new List<Section>();if(count>96)throw new InvalidDataException("Too many sections");for(int i=0;i<count;i++){long p=opt+size+i*40;sections.Add(new Section{VirtualSize=u32(p+8),Va=u32(p+12),Size=u32(p+16),Raw=u32(p+20)});}Func<uint,long> map=va=>{if(va<u32(opt+60))return va;foreach(var s in sections)if(va>=s.Va&&(ulong)va<(ulong)s.Va+Math.Max(s.VirtualSize,s.Size)){long offset=(long)s.Raw+va-s.Va;if(va-s.Va>=s.Size||offset>=f.Length)break;return offset;}throw new InvalidDataException("Unmapped RVA");};Func<long,string> str=p=>{f.Position=p;var chars=new List<byte>();for(int i=0;i<1024&&f.Position<f.Length;i++){byte c=r.ReadByte();if(c==0)return Encoding.ASCII.GetString(chars.ToArray());chars.Add(c);}throw new InvalidDataException("Invalid PE string");};uint exports=u32(dirs),imports=u32(dirs+8);if(imports!=0){long p=map(imports);for(int i=0;i<4096;i++,p+=20){uint name=u32(p+12);if(name==0)break;string dll=str(map(name));if(dll.IndexOf("steam",StringComparison.OrdinalIgnoreCase)<0)continue;b.Imports.Add(dll);uint table=u32(p);if(table==0)table=u32(p+16);long th=map(table);for(int j=0;j<10000;j++,th+=magic==0x20b?8:4){ulong entry=u32(th);if(magic==0x20b)entry|=(ulong)u32(th+4)<<32;if(entry==0)break;if((entry&(magic==0x20b?0x8000000000000000UL:0x80000000UL))!=0){b.Imports.Add(dll+"!#"+(entry&0xffff));continue;}b.Imports.Add(dll+"!"+str(map((uint)entry)+2));}}}if(exports!=0){long p=map(exports);uint names=u32(p+24),table=u32(p+32);if(names>100000)throw new InvalidDataException("Export limit");long t=map(table);for(uint i=0;i<names;i++){string name=str(map(u32(t+i*4)));if(name.StartsWith("Steam",StringComparison.Ordinal)||name.StartsWith("CreateInterface",StringComparison.Ordinal))b.Exports.Add(name);}}if(size>=dirs-opt+15*8&&u32(dirs+14*8)!=0){uint flags=u32(map(u32(dirs+14*8))+16);if(machine==0x14c&&(flags&1)!=0&&(flags&2)==0)b.Architecture="AnyCPU managed";else b.Architecture+=" managed";}}}
 public static string[] Architectures(string arch){return arch.StartsWith("AnyCPU")?new[]{"x86","x64"}:arch.StartsWith("x64")?new[]{"x64"}:arch.StartsWith("x86")?new[]{"x86"}:new string[0];}
 public static void Probe(AnalysisReport report,Action<string> log){var groups=new Dictionary<string,HashSet<string>>();foreach(var file in report.Files)foreach(string arch in Architectures(file.Architecture)){HashSet<string> set;if(!groups.TryGetValue(arch,out set)){set=new HashSet<string>();groups[arch]=set;}foreach(var e in file.Evidence){set.Add(e.Interface);string older;if(Fallbacks.TryGetValue(e.Interface,out older))set.Add(older);}}foreach(var pair in groups){if(pair.Value.Count==0)continue;if(pair.Key=="x64"){pair.Value.Add("SteamClient017");pair.Value.Add("SteamClient021");pair.Value.Add("SteamClient023");}if(pair.Key=="x64"&&!Environment.Is64BitOperatingSystem){foreach(var v in pair.Value)report.Probes[pair.Key+"|"+v]="UNKNOWN: 64-bit OS required";continue;}string temp=Path.Combine(Path.GetTempPath(),"LegacySteamProbe-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);try{string query=Path.Combine(temp,"query.txt");File.WriteAllLines(query,new List<string>(pair.Value).ToArray(),Encoding.ASCII);var si=new ProcessStartInfo(Core.Inside(Core.Base,"probes/SteamProbe-"+pair.Key+".exe"),"\""+report.Steam.TrimEnd(new char[]{'\\'})+"\" \""+query+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};uint appId;if(uint.TryParse(report.AppId,out appId)&&appId!=0){si.EnvironmentVariables["SteamAppId"]=report.AppId;si.EnvironmentVariables["SteamGameId"]=report.AppId;}var output=new StringBuilder();using(var p=new Process{StartInfo=si}){p.OutputDataReceived+=(s,e)=>{if(e.Data!=null)lock(output)output.AppendLine(e.Data);};p.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)lock(output)output.AppendLine("NOTE\t"+e.Data);};p.Start();p.BeginOutputReadLine();p.BeginErrorReadLine();if(!p.WaitForExit(30000)){p.Kill();p.WaitForExit();report.Warnings.Add(pair.Key+" probe timed out");}else p.WaitForExit();}string result=output.ToString();foreach(string line in result.Split(new char[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries)){string[] fields=line.Split(new char[]{'\t'},3);if(fields.Length>=3&&fields[0]=="RESULT")report.Probes[pair.Key+"|"+fields[1]]=fields[2];else report.Warnings.Add(pair.Key+" probe: "+line);}foreach(var v in pair.Value)if(!report.Probes.ContainsKey(pair.Key+"|"+v))report.Probes[pair.Key+"|"+v]="UNKNOWN: no valid probe result";log(pair.Key+" Steam interface probe complete");}catch(Exception e){report.Warnings.Add(pair.Key+" probe: "+e.Message);foreach(var v in pair.Value)report.Probes[pair.Key+"|"+v]="UNKNOWN: probe failed";}finally{Directory.Delete(temp,true);}}}
 public static string Render(AnalysisReport r){var b=new StringBuilder();b.AppendLine("LegacySteam interface analysis 0.2.0-test1");b.AppendLine("Game: "+r.Game+" AppID: "+r.AppId+"\nRoot: "+r.Root+"\nSteam: "+r.Steam+"\nScanned: "+r.Scanned);b.AppendLine("静态字符串属于接口需求线索，不证明游戏实际调用或启动必须依赖；未返回的接口也不单独证明启动故障原因。\nPRESENT=当前客户端返回接口；UNAVAILABLE=有效IPC上下文中未返回；UNKNOWN=探测无法确认。\n可点击生成兼容方案。本地规则匹配成功后才能安装实验性桥接；不保证任意游戏适配。\n");foreach(var f in r.Files){b.AppendLine("FILE "+f.File+" ["+f.Architecture+"] SHA256="+f.Hash);if(f.Error!=null)b.AppendLine(f.Error);foreach(var x in f.Imports)b.AppendLine("  IMPORT "+x);foreach(var x in f.Exports)b.AppendLine("  EXPORT "+x+" (库提供的导出，不代表游戏使用)");foreach(var e in f.Evidence)foreach(string arch in Architectures(f.Architecture).Length==0?new[]{"unknown"}:Architectures(f.Architecture)){string status; r.Probes.TryGetValue(arch+"|"+e.Interface,out status);b.AppendLine("  CANDIDATE "+e.Interface+" @0x"+e.Offset.ToString("X")+" "+e.Kind+" ["+arch+"] => "+(status??"UNKNOWN"));string older;if(Fallbacks.TryGetValue(e.Interface,out older)){string oldStatus;r.Probes.TryGetValue(arch+"|"+older,out oldStatus);b.AppendLine("    RULE CANDIDATE "+older+" => "+(oldStatus??"UNKNOWN")+";已有项目适配经验，需要校验函数布局/参数/游戏校验，不能直接替换版本字符串");}}}b.AppendLine("\nPROBE RESULTS");foreach(var p in r.Probes)b.AppendLine(p.Key+" = "+p.Value);b.AppendLine("\nWARNINGS");foreach(var w in r.Warnings)b.AppendLine(w);return b.ToString();}
}
